create table if not exists public.v28_autonomy_policies (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,policy_key text not null,enabled boolean not null default true,auto_execute boolean not null default false,minimum_score numeric(8,4) not null default 85 check(minimum_score between 0 and 100),maximum_risk_score numeric(8,4) not null default 35 check(maximum_risk_score between 0 and 100),maximum_cost numeric(24,8) not null default 0 check(maximum_cost>=0),allowed_actions text[] not null default array['internal_transfer','recommended_supplier']::text[],require_approval_below_score numeric(8,4) not null default 70 check(require_approval_below_score between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,policy_key));
create table if not exists public.v28_agent_runs (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,worker_id text not null,status text not null default 'running' check(status in ('running','completed','failed')),decisions_evaluated integer not null default 0,auto_executed integer not null default 0,approval_required integer not null default 0,escalated integer not null default 0,blocked integer not null default 0,failed integer not null default 0,started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.v28_agent_actions (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,run_id uuid not null references public.v28_agent_runs(id) on delete cascade,candidate_id uuid not null references public.v27_decision_candidates(id) on delete restrict,action_mode text not null check(action_mode in ('auto_execute','approval_required','escalated','blocked')),execution_status text not null default 'pending' check(execution_status in ('pending','executed','pending_external','awaiting_approval','blocked','failed')),policy_key text,reason text,policy_snapshot jsonb not null default '{}'::jsonb,result jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),executed_at timestamptz);
create unique index if not exists uq_v28_candidate_run on public.v28_agent_actions(run_id,candidate_id);
create table if not exists public.v28_outcome_measurements (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,agent_action_id uuid not null references public.v28_agent_actions(id) on delete cascade,measured_at timestamptz not null default now(),outcome text not null check(outcome in ('service_recovered','partially_recovered','no_recovery','failed','pending')),shortage_before numeric(24,8) not null default 0,shortage_after numeric(24,8) not null default 0,stockout_day_before integer,stockout_day_after integer,cost_actual numeric(24,8) not null default 0,notes jsonb not null default '{}'::jsonb);
create unique index if not exists uq_v28_one_measurement_per_action on public.v28_outcome_measurements(agent_action_id);
alter table public.v28_autonomy_policies enable row level security; alter table public.v28_agent_runs enable row level security; alter table public.v28_agent_actions enable row level security; alter table public.v28_outcome_measurements enable row level security;
drop policy if exists v28_policy_select on public.v28_autonomy_policies; create policy v28_policy_select on public.v28_autonomy_policies for select using(is_member(business_id)); drop policy if exists v28_runs_select on public.v28_agent_runs; create policy v28_runs_select on public.v28_agent_runs for select using(is_member(business_id)); drop policy if exists v28_actions_select on public.v28_agent_actions; create policy v28_actions_select on public.v28_agent_actions for select using(is_member(business_id)); drop policy if exists v28_outcomes_select on public.v28_outcome_measurements; create policy v28_outcomes_select on public.v28_outcome_measurements for select using(is_member(business_id));
revoke insert,update,delete on public.v28_autonomy_policies from authenticated; revoke insert,update,delete on public.v28_agent_runs from authenticated; revoke insert,update,delete on public.v28_agent_actions from authenticated; revoke insert,update,delete on public.v28_outcome_measurements from authenticated;
create or replace function public.install_v28_default_autonomy_policy(p_business_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; insert into public.v28_autonomy_policies(business_id,policy_key,enabled,auto_execute,minimum_score,maximum_risk_score,maximum_cost,allowed_actions,require_approval_below_score) values(p_business_id,'balanced-safe',true,false,88,35,0,array['internal_transfer','recommended_supplier']::text[],72) on conflict(business_id,policy_key) do nothing; select count(*) into n from public.v28_autonomy_policies where business_id=p_business_id; return n; end $$; grant execute on function public.install_v28_default_autonomy_policy(uuid) to authenticated;
create or replace view public.view_v28_agent_control_tower with (security_invoker=true) as select a.*,c.location_id,c.ingredient_id,c.unit,c.action_type,c.quantity,c.total_score,c.risk_score,c.projected_shortage_quantity,l.code location_code,l.name location_name,i.name ingredient_name,r.status run_status,r.worker_id,r.started_at run_started_at from public.v28_agent_actions a join public.v27_decision_candidates c on c.id=a.candidate_id join public.v28_agent_runs r on r.id=a.run_id join public.locations l on l.id=c.location_id join public.ingredients i on i.id=c.ingredient_id;
create or replace function public.v28_run_agent(p_business_id uuid,p_worker_id text,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public as $$ declare run_id uuid;c record;p record;mode text;reason text;evaluated integer:=0;approvals integer:=0;escalated integer:=0;blocked integer:=0;failed integer:=0; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_limit not between 1 and 500 then raise exception 'Limit must be between 1 and 500'; end if; perform pg_advisory_xact_lock(hashtextextended(p_business_id::text,2800)); select * into p from public.v28_autonomy_policies where business_id=p_business_id and enabled order by updated_at desc,policy_key limit 1; if p.id is null then raise exception 'No enabled V2.8 autonomy policy installed'; end if; insert into public.v28_agent_runs(business_id,worker_id) values(p_business_id,p_worker_id) returning id into run_id; for c in select * from public.v27_decision_candidates where business_id=p_business_id and recommendation_status='recommended' order by total_score desc,risk_score asc,location_id,ingredient_id,id limit p_limit loop evaluated:=evaluated+1; mode:='approval_required'; reason:='policy_auto_execute_disabled'; if not (c.action_type=any(p.allowed_actions)) then mode:='blocked';reason:='action_not_allowed_by_policy';blocked:=blocked+1; elsif c.total_score<p.require_approval_below_score then mode:='escalated';reason:='score_below_approval_threshold';escalated:=escalated+1; elsif c.total_score>=p.minimum_score and c.risk_score<=p.maximum_risk_score and (p.maximum_cost=0 or c.projected_cost<=p.maximum_cost) and p.auto_execute then mode:='approval_required';reason:='eligible_but_execution_boundary_requires_governed_executor';approvals:=approvals+1; else approvals:=approvals+1; end if; insert into public.v28_agent_actions(business_id,run_id,candidate_id,action_mode,execution_status,policy_key,reason,policy_snapshot,result) values(p_business_id,run_id,c.id,mode,case when mode in ('blocked') then 'blocked' else 'awaiting_approval' end,p.policy_key,reason,to_jsonb(p),jsonb_build_object('execution_boundary','V2.x governed executor')); end loop; update public.v28_agent_runs set status='completed',completed_at=now(),decisions_evaluated=evaluated,approval_required=approvals,escalated=escalated,blocked=blocked,failed=failed where id=run_id; return jsonb_build_object('run_id',run_id,'evaluated',evaluated,'approval_required',approvals,'escalated',escalated,'blocked',blocked,'failed',failed,'policy_key',p.policy_key); exception when others then if run_id is not null then update public.v28_agent_runs set status='failed',completed_at=now() where id=run_id; end if; raise; end $$; grant execute on function public.v28_run_agent(uuid,text,integer) to authenticated;
create or replace function public.v28_measure_outcome(p_action_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare a record;c record;after_short numeric;before_short numeric;before_day integer;after_day integer;outcome text; begin select * into a from public.v28_agent_actions where id=p_action_id; if a.id is null then raise exception 'Agent action not found'; end if; if not is_member(a.business_id) then raise exception 'Tenant access denied'; end if; select * into c from public.v27_decision_candidates where id=a.candidate_id; before_short:=greatest(0,coalesce(c.projected_shortage_quantity,0)); select greatest(0,d.reorder_point-d.current_stock) into after_short from public.view_v20_location_reorder d where d.business_id=a.business_id and d.location_id=c.location_id and d.ingredient_id=c.ingredient_id and d.unit=c.unit limit 1; after_short:=coalesce(after_short,0); before_day:=c.projected_stockout_day; select case when d.current_stock>0 and d.average_daily_demand>0 then floor(d.current_stock/d.average_daily_demand)::integer else null end into after_day from public.view_v20_location_reorder d where d.business_id=a.business_id and d.location_id=c.location_id and d.ingredient_id=c.ingredient_id and d.unit=c.unit limit 1; outcome:=case when after_short=0 then 'service_recovered' when after_short<before_short then 'partially_recovered' else 'no_recovery' end; insert into public.v28_outcome_measurements(business_id,agent_action_id,outcome,shortage_before,shortage_after,stockout_day_before,stockout_day_after,notes) values(a.business_id,a.id,outcome,before_short,after_short,before_day,after_day,jsonb_build_object('measured_by',auth.uid())) on conflict(agent_action_id) do update set measured_at=now(),outcome=excluded.outcome,shortage_before=excluded.shortage_before,shortage_after=excluded.shortage_after,stockout_day_before=excluded.stockout_day_before,stockout_day_after=excluded.stockout_day_after,notes=excluded.notes; return jsonb_build_object('action_id',a.id,'outcome',outcome,'shortage_before',before_short,'shortage_after',after_short); end $$; grant execute on function public.v28_measure_outcome(uuid) to authenticated;